// ═══════════════════════════════════════════════════════════════════
// 电影大师 · 图片归位（v1.3）
//  · 按钮「图片归位」旁有一个正文标签输入框（例如 </content>）
//  · 填了标签：只有「所有图片都在该标签之后」才算堆在末尾，才归位
//  · 不填标签：退回旧规则（所有图片都在消息最末）
//  · 不调用模型，纯文本比对；按钮点击有日志与提示
// ═══════════════════════════════════════════════════════════════════

const CFG = {
  auto: true,
  dryRun: false,
  maxParagraphs: 60,
  minScore: 0.15
};

const STORE_KEY = 'fm_move_body_tag';
let bodyTag = '';
try { bodyTag = (localStorage.getItem(STORE_KEY) || '').trim(); } catch (e) {}
let boxEl = null;
let askedOnce = false;

// ── API 双路查找 ────────────────────────────────────────────────
const TH = (typeof TavernHelper !== 'undefined' && TavernHelper) || {};
const api = (n) => (TH && typeof TH[n] === 'function') ? TH[n]
  : (typeof globalThis[n] === 'function' ? globalThis[n] : null);

const getMsgs   = api('getChatMessages');
const setMsgs   = api('setChatMessages');
const onEvent   = api('eventOn');
const getBtnEvt = api('getButtonEvent');
const getLastId = api('getLastMessageId');
const EVENTS    = (TH && TH.tavern_events) || globalThis.tavern_events || {};
const toast     = (TH && TH.toastr) || globalThis.toastr;

const log = (...a) => console.log('[FM-move]', ...a);
const seen = new Set();

const UNIT_RE = /<imgthink>[\s\S]*?<\/imgthink>\s*<image[^>]*>[\s\S]*?<\/image>|<image[^>]*>[\s\S]*?<\/image>/g;
const VAR_RE  = /<[Uu]pdate[Vv]ariable>[\s\S]*?<\/[Uu]pdate[Vv]ariable>/g;

// ═══════════════════════════════════════════════════════════════
// 正文标签输入框：插到「图片归位」按钮旁边
// ═══════════════════════════════════════════════════════════════
function docRef() {
  try { if (typeof window !== 'undefined' && window.parent && window.parent.document) return window.parent.document; } catch (e) {}
  try { if (typeof document !== 'undefined') return document; } catch (e) {}
  return null;
}

function findButton(doc) {
  if (!doc || !doc.querySelectorAll) return null;
  const list = doc.querySelectorAll('button, .menu_button, [role="button"]');
  for (const b of list) {
    const t = (b.textContent || '').trim();
    if (t === '图片归位' || t.indexOf('图片归位') >= 0) return b;
  }
  return null;
}

function styleLike(inp, btn, doc) {
  try {
    const win = (doc && doc.defaultView) || (typeof window !== 'undefined' ? window : null);
    const cs = win && win.getComputedStyle ? win.getComputedStyle(btn) : null;
    const bg = cs && cs.backgroundColor && cs.backgroundColor !== 'rgba(0, 0, 0, 0)' ? cs.backgroundColor : '';
    const bd = cs && cs.borderColor ? cs.borderColor : '';
    const bc = (bd && bd !== 'rgba(0, 0, 0, 0)') ? bd : (bg || 'rgba(255,255,255,.25)');
    const parts = [
      'width:160px', 'box-sizing:border-box', 'margin-right:6px', 'vertical-align:middle',
      'height:' + (cs && cs.height && cs.height !== 'auto' ? cs.height : '26px'),
      'padding:0 8px',
      'color:#ffffff',
      'background-color:' + (bg || 'rgba(255,255,255,.12)'),
      'border:1px solid ' + bc,
      'border-radius:' + (cs && cs.borderRadius ? cs.borderRadius : '6px'),
      'font-family:' + (cs && cs.fontFamily ? cs.fontFamily : 'inherit'),
      'font-size:' + (cs && cs.fontSize ? cs.fontSize : '12px'),
      'line-height:1.2', 'outline:none', 'caret-color:#ffffff', '-webkit-text-fill-color:#ffffff'
    ];
    inp.style.cssText = parts.join(';') + ';';
  } catch (e) {
    inp.style.cssText = 'width:132px;height:26px;margin-right:6px;padding:0 8px;box-sizing:border-box;vertical-align:middle;'
      + 'color:#fff;-webkit-text-fill-color:#fff;caret-color:#fff;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.25);border-radius:6px;font-size:12px;';
  }
}

function mountPlaceholderStyle(doc) {
  try {
    if (doc.getElementById && doc.getElementById('fm-move-tag-css')) return;
    const st = doc.createElement('style');
    st.id = 'fm-move-tag-css';
    st.textContent = '#fm-move-tag::placeholder{color:rgba(255,255,255,.55);opacity:1;}'
      + '#fm-move-tag:focus{border-color:rgba(255,255,255,.65);box-shadow:none;}';
    (doc.head || doc.documentElement).appendChild(st);
  } catch (e) {}
}

function mountBox() {
  const doc = docRef();
  if (!doc) return false;
  if (doc.getElementById && doc.getElementById('fm-move-tag')) {
    boxEl = doc.getElementById('fm-move-tag');
    const b0 = findButton(doc);
    if (b0) styleLike(boxEl, b0, doc);
    return true;
  }
  const btn = findButton(doc);
  if (!btn || !btn.parentNode) return false;
  try {
    const inp = doc.createElement('input');
    inp.id = 'fm-move-tag';
    inp.type = 'text';
    inp.value = bodyTag;
    inp.placeholder = '正文标签，如 content';
    inp.title = '正文范围：填标签名（多个用、隔开，如 content、draft），只拿这些标签内部的段落匹配图片；留空=整条消息都算正文。';
    mountPlaceholderStyle(doc);
    styleLike(inp, btn, doc);
    inp.addEventListener('input', () => saveTag(inp.value));
    inp.addEventListener('change', () => saveTag(inp.value));
    btn.parentNode.insertBefore(inp, btn);
    boxEl = inp;
    log('已挂载正文标签输入框', bodyTag ? '（当前：' + bodyTag + '）' : '');
    return true;
  } catch (e) { log('挂载输入框失败', e); return false; }
}

function saveTag(v) {
  bodyTag = String(v || '').trim();
  try { localStorage.setItem(STORE_KEY, bodyTag); } catch (e) {}
}

function readBox() {
  try {
    const doc = docRef();
    const el = (doc && doc.getElementById && doc.getElementById('fm-move-tag')) || boxEl;
    if (el && typeof el.value === 'string') saveTag(el.value);
  } catch (e) {}
  return bodyTag;
}

// 面板可能是后渲染/会重绘：定时检查，缺了就补挂（开销可忽略）
let mountTries = 0;
const mountTimer = docRef() ? setInterval(() => {
  mountTries++;
  let ok = false;
  try { ok = mountBox(); } catch (e) {}
  if (ok) { if (mountTries > 1) log('正文标签输入框已就位'); }
  else if (mountTries === 1) log('暂未找到「图片归位」按钮，继续等待渲染…');
  if (mountTries > 2400) clearInterval(mountTimer);   // 约 1 小时后停止
}, 1500) : null;

// ═══════════════════════════════════════════════════════════════
// 文本工具
// ═══════════════════════════════════════════════════════════════
function grams(s) {
  const t = String(s || '').replace(/[^\u4e00-\u9fa5A-Za-z0-9]/g, '');
  const m = new Map();
  for (const ch of t) m.set(ch, (m.get(ch) || 0) + 0.35);
  for (let i = 0; i + 1 < t.length; i++) { const b = t.slice(i, i + 2); m.set(b, (m.get(b) || 0) + 1); }
  return m;
}

function scan(text) {
  const units = [];
  UNIT_RE.lastIndex = 0;
  let m;
  while ((m = UNIT_RE.exec(text)) !== null) units.push({ start: m.index, end: m.index + m[0].length, raw: m[0] });
  return units;
}

function splitParagraphs(body) {
  let parts = body.split(/\n{2,}/).map(p => p.trim()).filter(Boolean);
  if (parts.length < 2) parts = body.split(/\n(?=\S)/).map(p => p.trim()).filter(Boolean);
  return parts.slice(0, CFG.maxParagraphs);
}

function thinkCore(raw) {
  const m = raw.match(/<imgthink>([\s\S]*?)<\/imgthink>/i);
  if (!m) return (raw.match(/【([^】]{0,40})】/) || [])[1] || '';
  let t = m[1];
  const core = t.match(/(?:原文视觉核心|视觉核心|视觉要点)[^\n]*[:：]?\s*([\s\S]{10,400}?)(?:\n\s*【|\n\s*\[S|\n\s*┌|\n\s*│)/);
  if (core && core[1] && core[1].trim().length >= 10) t = core[1];
  return t.replace(/[\[\]{}()<>]/g, ' ');
}

function assign(paras, texts) {
  const n = paras.length, m = texts.length;
  const pg = paras.map(p => grams(p));
  const pw = pg.map(g => { let t = 0; for (const w of g.values()) t += w; return Math.sqrt(Math.max(t, 0.001)); });
  const df = new Map();
  for (const g of pg) for (const k of g.keys()) df.set(k, (df.get(k) || 0) + 1);

  // 余弦式相似度：长段落不再无脑吸图
  const sims = [];
  for (let i = 0; i < m; i++) {
    const ug = grams(texts[i]);
    let total = 0;
    for (const w of ug.values()) total += w;
    const norm = Math.sqrt(Math.max(total, 0.001));
    const row = new Array(n + 1).fill(0);
    for (let p = 1; p <= n; p++) {
      let s = 0;
      for (const [g, w] of ug) if (pg[p - 1].has(g)) s += w / (df.get(g) || 1);
      row[p] = s / (norm * pw[p - 1]);
    }
    sims.push(row);
  }

  const order = [...Array(m).keys()].sort((x, y) => {
    const bx = Math.max(...sims[x].slice(1)), by = Math.max(...sims[y].slice(1));
    return by - bx;
  });

  const used = new Array(n + 1).fill(0);
  const out = new Array(m).fill(0);
  const info = [];
  const spread = n >= m * 2;          // 段落够多就一段一张，不够才允许挤在一起

  for (const i of order) {
    const expect = Math.min(n, Math.max(1, Math.round((i + 1) * n / m)));
    let pick = 0, best = -1;
    for (let p = 1; p <= n; p++) {
      if (spread && used[p]) continue;
      if (sims[i][p] > best) { best = sims[i][p]; pick = p; }
    }
    let how = '相似度';
    if (pick === 0 || best < CFG.minScore) {
      // 相似度不够：按比例位置落，尽量挑空的段
      how = '位置兜底';
      const cands = [];
      for (let p = 1; p <= n; p++) if (!spread || !used[p]) cands.push(p);
      if (!cands.length) for (let p = 1; p <= n; p++) cands.push(p);
      cands.sort((x, y) => Math.abs(x - expect) - Math.abs(y - expect));
      pick = cands[0];
      best = sims[i][pick];
    }
    used[pick]++;
    out[i] = pick;
    info.push({ img: i + 1, para: pick, sim: +best.toFixed(3), how });
  }
  return { pos: out, info };
}

// ═══════════════════════════════════════════════════════════════
// 判定：所有图片是否都“堆在末尾”（标签优先）
// ═══════════════════════════════════════════════════════════════
// 输入解析：content、draft  或  </content> 都行，多个用、逗号分隔
function parseTags(v) {
  const out = [];
  String(v || '').split(/[、,，;；\s]+/).forEach(x => {
    const m = x.replace(/[<>\/]/g, '').trim().match(/^[A-Za-z0-9_:.\-]+/);
    if (m && out.indexOf(m[0]) < 0) out.push(m[0]);
  });
  return out;
}

// 连在一起的图：相邻两张之间只有空白
function findRuns(units, text) {
  const runs = [];
  if (!units.length) return runs;
  let cur = [0];
  for (let i = 1; i < units.length; i++) {
    const gap = text.slice(units[i - 1].end, units[i].start);
    if (/^\s*$/.test(gap)) cur.push(i);
    else { runs.push(cur); cur = [i]; }
  }
  runs.push(cur);
  return runs;
}

// 把要移动的图从文本里摘掉，其余原样
function stripUnits(text, units, idxSet) {
  let base = '', cursor = 0;
  const moved = [];
  units.forEach((u, i) => {
    if (!idxSet.has(i)) return;
    base += text.slice(cursor, u.start);
    moved.push(u);
    cursor = u.end;
  });
  base += text.slice(cursor);
  return { base, moved };
}

// 所有标签内容的区域（多个标签取并集，重叠自动合并）
function regions(base, tags) {
  if (!tags.length) return [{ start: 0, end: base.length, tag: '(整条消息)' }];
  const out = [];
  for (const name of tags) {
    const re = new RegExp('<' + name + '(?:\\s[^>]*)?>([\\s\\S]*?)<\\/' + name + '\\s*>', 'gi');
    let m;
    while ((m = re.exec(base)) !== null) {
      const gt = m[0].indexOf('>');
      const start = m.index + gt + 1;
      out.push({ start, end: start + m[1].length, tag: name });
    }
  }
  out.sort((x, y) => x.start - y.start);
  const merged = [];
  for (const r of out) {
    const last = merged[merged.length - 1];
    if (last && r.start <= last.end) last.end = Math.max(last.end, r.end);
    else merged.push({ start: r.start, end: r.end, tag: r.tag });
  }
  return merged;
}

// 区域内部按空行切段，记录每段的绝对结束位置
function paragraphsIn(base, r) {
  const txt = base.slice(r.start, r.end);
  const out = [];
  let pos = 0, m;
  const bounds = [];
  const re = /\n{2,}/g;
  while ((m = re.exec(txt)) !== null) { bounds.push([pos, m.index]); pos = m.index + m[0].length; }
  bounds.push([pos, txt.length]);
  for (const [s0, e0] of bounds) {
    let s = s0, e = e0;
    while (s < e && /\s/.test(txt[s])) s++;
    while (e > s && /\s/.test(txt[e - 1])) e--;
    if (e <= s) continue;
    out.push({ start: r.start + s, end: r.start + e, text: txt.slice(s, e) });
  }
  return out;
}

async function lastMessageId() {
  try { if (getLastId) { const id = await getLastId(); if (id !== null && id !== undefined) return id; } } catch (e) {}
  try { if (getMsgs) { const l = await getMsgs(-1); if (l && l.length) return l[l.length - 1].message_id; } } catch (e) {}
  return null;
}

async function relocate(messageId) {
  const t0 = performance.now();
  if (!getMsgs || !setMsgs) return { ok: false, reason: '缺少 getChatMessages/setChatMessages' };
  let list;
  try { list = await getMsgs(messageId); } catch (e) { return { ok: false, reason: '取消息失败：' + e }; }
  const msg = (list || [])[0];
  if (!msg) return { ok: false, reason: '取不到第 ' + messageId + ' 楼' };
  if (msg.role !== 'assistant') return { ok: false, reason: '最新一楼不是 AI 回复' };

  const text = msg.message || '';
  const units = scan(text);

  // 触发：只要有 ≥2 张图连在一起
  const runs = findRuns(units, text);
  const idxSet = new Set();
  runs.forEach(r => { if (r.length >= 2) r.forEach(i => idxSet.add(i)); });
  if (!idxSet.size) return { ok: false, reason: '无需归位：没有连在一起的图片' };

  const { base, moved } = stripUnits(text, units, idxSet);
  const tags = parseTags(bodyTag);
  let regs = regions(base, tags);
  let tagNote = tags.length ? tags.join('+') : '整条消息';
  if (!regs.length) {   // 标签没命中：退回整条消息，别让图卡在原处
    regs = [{ start: 0, end: base.length, tag: '(未命中，整条)' }];
    tagNote = '标签未命中，按整条消息';
    log('没找到正文标签 ' + tags.join('、') + '，改按整条消息匹配');
  }

  // 收集所有标签内的段落
  let paras = [];
  for (const r of regs) paras = paras.concat(paragraphsIn(base, r));
  if (!paras.length) return { ok: false, reason: '标签内没有正文段落' };

  // 单独成段的图并到上一段，避免它被当成一个"段落"
  const merged = [];
  for (const p of paras) {
    const onlyImg = /^\s*(<imgthink>[\s\S]*?<\/imgthink>\s*)?<image[^>]*>[\s\S]*?<\/image>\s*$/.test(p.text);
    if (onlyImg && merged.length) {
      const last = merged[merged.length - 1];
      last.text += '\n\n' + p.text;
      last.end = p.end;
    } else merged.push(p);
  }
  if (!merged.length) return { ok: false, reason: '标签内没有正文段落' };

  // 比对用文本：剔除图片自身内容（图片在标签内也不会自我匹配）
  const clean = merged.map(p =>
    p.text.replace(/<imgthink>[\s\S]*?<\/imgthink>\s*<image[^>]*>[\s\S]*?<\/image>|<image[^>]*>[\s\S]*?<\/image>/g, ' '));
  const asg = assign(clean, moved.map(u => thinkCore(u.raw)));
  const pos = asg.pos;
  asg.info.forEach(it => log('图' + it.img + ' → 第' + it.para + '段（相似度 ' + it.sim + '，' + it.how + '）'));

  const groups = {};
  pos.forEach((p, i) => { (groups[p] = groups[p] || []).push(moved[i].raw.trim()); });

  // 在每段末尾直接插入，其余文本一个字节都不动
  const edits = Object.keys(groups).map(k => {
    const pi = Number(k) - 1;
    return { at: merged[pi].end, text: '\n\n' + groups[k].join('\n\n') };
  }).sort((a, b) => b.at - a.at);

  let out = base;
  for (const e of edits) out = out.slice(0, e.at) + e.text + out.slice(e.at);

  if (out.trim() === text.trim()) return { ok: false, reason: '整理后无变化' };
  if (CFG.dryRun) { log('dryRun：\n' + out.slice(0, 800)); return { ok: false, reason: 'dryRun 已打印' }; }

  try { await setMsgs([{ message_id: messageId, message: out }]); }
  catch (e) { return { ok: false, reason: '写回失败：' + e }; }

  const ms = (performance.now() - t0).toFixed(2);
  log('已归位', messageId, '移动', moved.length, '张 → 段落', pos.join(','),
    '| 标签范围:', tagNote, '| 段落数:', merged.length, '| 耗时', ms + 'ms');
  return {
    ok: true,
    reason: '移动 ' + moved.length + ' 张：' + pos.map((a, i) => '图' + (i + 1) + '→第' + a + '段').join(' ') +
      '（' + tagNote + ' 内共 ' + merged.length + ' 段）',
    ms
  };
}

// ═══════════════════════════════════════════════════════════════
// 自动 + 按钮
// ═══════════════════════════════════════════════════════════════
if (onEvent && CFG.auto) {
  onEvent(EVENTS.MESSAGE_RECEIVED || 'message_received', async (id) => {
    if (seen.has(id)) return;
    seen.add(id);
    try { await relocate(id); } catch (e) { log('自动归位异常', e); }
  });
  log('已挂载自动归位');
}

if (!getBtnEvt) {
  log('⚠️ 没有 getButtonEvent，按钮点击收不到；请用自动流程');
} else if (onEvent) {
  const ev = getBtnEvt('图片归位');
  log('按钮事件名：', ev);
  onEvent(ev, async () => {
    log('按钮点击：图片归位');
    readBox();                                  // 先把输入框内容存下来
    if (!boxEl && !bodyTag && !askedOnce) {     // 输入框没挂上时兜底问一次
      askedOnce = true;
      try {
        const v = (typeof prompt === 'function')
          ? prompt('请输入正文标签（例如 </content>）。\n留空 = 按“所有图片都在消息最末”判断：', '')
          : null;
        if (v !== null && v !== undefined) saveTag(v);
      } catch (e) {}
    }
    log('正文标签：', bodyTag || '（空，按消息末尾判断）');
    try {
      const id = await lastMessageId();
      if (id === null || id === undefined) {
        toast && toast.error && toast.error('图片归位：找不到最新楼层');
        return;
      }
      const r = await relocate(id);
      log('按钮结果：', r);
      if (toast) {
        if (r.ok) toast.success && toast.success('图片已归位：' + r.reason);
        else { const f = toast.warning || toast.info || toast.success; f && f('图片归位：' + r.reason); }
      }
    } catch (e) {
      log('按钮异常', e);
      toast && toast.error && toast.error('图片归位异常：' + e);
    }
  });
} else {
  log('⚠️ 没有 eventOn，按钮与自动都无法绑定');
}

globalThis.FM_move = { relocate, lastMessageId, scan, findRuns, regions, parseTags, splitParagraphs, assign, thinkCore, readBox, mountBox,
  getTag: () => bodyTag, setTag: (v) => saveTag(v) };
log('电影大师图片归位 v1.3 加载完成', CFG, '标签:', bodyTag || '(空)');
